int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int L, C;
    if (!(cin >> L >> C)) return 0;

    vector<vector<string>> grid(L, vector<string>(C));
    vector<long long> row_sum(L);
    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            cin >> grid[i][j];
        }
        cin >> row_sum[i];
    }

    vector<long long> col_sum(C);
    for (int j = 0; j < C; ++j) {
        cin >> col_sum[j];
    }

    map<string, long long> val;
    set<string> all_vars;
    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            all_vars.insert(grid[i][j]);
        }
    }

    int remaining = all_vars.size();

    while (remaining > 0) {
        bool progress = false;

        // Verificar linhas
        for (int i = 0; i < L; ++i) {
            set<string> unk;
            for (int j = 0; j < C; ++j) {
                if (val.find(grid[i][j]) == val.end()) {
                    unk.insert(grid[i][j]);
                }
            }
