                long long current_sum = 0;
                int count_target = 0;
                for (int j = 0; j < C; ++j) {
                    if (grid[i][j] == target) {
                        count_target++;
                    } else {
                        current_sum += val[grid[i][j]];
                    }
                }
                val[target] = (row_sum[i] - current_sum) / count_target;
                remaining--;
                progress = true;
                break;
            }
        }

        if (progress) continue;

        // Verificar colunas
        for (int j = 0; j < C; ++j) {
            set<string> unk;
            for (int i = 0; i < L; ++i) {
                if (val.find(grid[i][j]) == val.end()) {
                    unk.insert(grid[i][j]);
                }
            }
            if (unk.size() == 1) {
                string target = *unk.begin();
                long long current_sum = 0;
                int count_target = 0;
                for (int i = 0; i < L; ++i) {
                    if (grid[i][j] == target) {
                        count_target++;
