                        current_sum += val[grid[i][j]];
                    }
                }
                val[target] = (col_sum[j] - current_sum) / count_target;
                remaining--;
                progress = true;
                break;
            }
        }
    }

    for (auto const& [k, v] : val) {
        cout << k << " " << v << "\n";
    }

    return 0;
}
